import React from "react";
import ReactDOM from "react-dom/client";
import App from "./app";
import { LanguageProvider } from "./Languagecontext";

const root = ReactDOM.createRoot(
  document.getElementById("root")
);

root.render(
  <React.StrictMode>
    <LanguageProvider>
      <App />
    </LanguageProvider>
  </React.StrictMode>
);
